    {
      "severity": "low",
      "file": "src/theme.ts / public/theme.css",
      "issue": "Several components (e.g., `EmptyState` action button, `MiniFAB` background) use hard‑coded hex colors (`#0061A4`, `#015958`) instead of the exported design tokens.",
